const canvas=document.querySelector('#orbit'),ctx=canvas.getContext('2d');let paused=matchMedia('(prefers-reduced-motion: reduce)').matches,phase=0;
function fit(c){const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d)}const x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);return [r.width,r.height,x]}
function drawOrbit(c,t,e=.42){let[w,h,x]=fit(c);x.clearRect(0,0,w,h);let a=Math.min(w*.36,h*.43),b=a*Math.sqrt(1-e*e),cx=w/2,cy=h/2;const angle=-.4;x.save();x.translate(cx,cy);x.rotate(angle);x.strokeStyle='#82966b42';x.lineWidth=1;[.64,1,1.35].forEach(s=>{x.beginPath();x.ellipse(0,0,a*s,b*s,0,0,Math.PI*2);x.stroke()});x.setLineDash([3,5]);x.strokeStyle='#86997255';x.beginPath();x.moveTo(-a*1.55,0);x.lineTo(a*1.55,0);x.moveTo(a*e,-b*1.6);x.lineTo(a*e,b*1.6);x.stroke();x.setLineDash([]);let E=t;for(let i=0;i<8;i++)E-=(E-e*Math.sin(E)-t)/(1-e*Math.cos(E));const px=a*Math.cos(E),py=b*Math.sin(E),sx=a*e;let E2=t+.6;for(let i=0;i<8;i++)E2-=(E2-e*Math.sin(E2)-t-.6)/(1-e*Math.cos(E2));x.fillStyle='#d3ef970b';x.beginPath();x.moveTo(sx,0);x.lineTo(px,py);x.ellipse(0,0,a,b,0,E,E2);x.closePath();x.fill();x.strokeStyle='#d3ef9766';x.beginPath();x.moveTo(sx,0);x.lineTo(px,py);x.stroke();let g=x.createRadialGradient(sx,0,1,sx,0,35);g.addColorStop(0,'#d3ef9766');g.addColorStop(1,'#d3ef9700');x.fillStyle=g;x.beginPath();x.arc(sx,0,35,0,7);x.fill();x.fillStyle='#d3ef97';x.beginPath();x.arc(sx,0,7,0,7);x.fill();x.strokeStyle='#d3ef9788';x.beginPath();x.arc(sx,0,13,0,7);x.stroke();x.fillStyle='#eda76c';x.beginPath();x.arc(px,py,5,0,7);x.fill();x.restore();x.fillStyle='#839577';x.font='11px monospace';x.fillText('y',cx+a*e,26);x.fillText('x',w-18,cy);x.fillStyle='#d3ef97';x.fillText('M',cx+a*e*Math.cos(angle)-22,cy-a*e*.4-15);x.fillStyle='#a1b48e';x.fillText('r(t)',cx+20,cy-10)}
let last=0;function animate(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!paused)phase+=dt*.42;drawOrbit(canvas,phase);if(typeof drawLab==='function')drawLab(dt);requestAnimationFrame(animate)}requestAnimationFrame(animate);
function motionLabel(){document.body.classList.toggle('motion-paused',paused);document.querySelector('#motion').textContent=paused?'▷ Resume motion':'Ⅱ Pause motion';document.querySelector('#motion').setAttribute('aria-pressed',String(paused))}motionLabel();document.querySelector('#motion').onclick=()=>{paused=!paused;motionLabel()};function clock(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat('en',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kolkata'}).format(new Date())+' IST'}clock();setInterval(clock,10000);
const titles={projects:'Selected work',experience:'Experience',about:'About Sudhanshu',lab:'Physics playground',notes:'Field notes',terminal:'Terminal',contact:'Open a conversation'};let topZ=100;const wins=new Map();const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function front(el){el.style.zIndex=++topZ}
function openApp(id){if(!titles[id])return;let w=wins.get(id);if(w){w.hidden=false;document.querySelector(`[data-restore="${id}"]`)?.remove();front(w);w.focus({preventScroll:true});return w}w=document.createElement('section');w.className='window';w.tabIndex=-1;w.dataset.app=id;w.setAttribute('role','dialog');w.setAttribute('aria-label',titles[id]);w.innerHTML=`<div class="window-title"><span>φ / ${titles[id].toLowerCase()} <span class="muted">— field notes</span></span><div class="window-controls"><button data-action="minimize" aria-label="Minimize ${titles[id]}">−</button><button data-action="maximize" aria-label="Maximize ${titles[id]}">□</button><button data-action="close" aria-label="Close ${titles[id]}">×</button></div></div><div class="window-content"></div>`;wins.set(id,w);document.querySelector('#windows').append(w);front(w);w._opener=document.activeElement;w.addEventListener('pointerdown',()=>front(w));w.addEventListener('focusin',()=>front(w));w.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='close')closeApp(id);if(b.dataset.action==='maximize'){w.classList.toggle('maximized');b.setAttribute('aria-label',(w.classList.contains('maximized')?'Restore ':'Maximize ')+titles[id])}if(b.dataset.action==='minimize'){w.hidden=true;let b2=document.createElement('button');b2.dataset.restore=id;b2.textContent=titles[id];b2.onclick=()=>openApp(id);document.querySelector('#restore-bar').append(b2);w._opener?.focus({preventScroll:true})}});dragWindow(w);renderApp(id,w.querySelector('.window-content'));w.focus({preventScroll:true});return w}
function closeApp(id){let w=wins.get(id);if(!w)return;w.remove();wins.delete(id);document.querySelector(`[data-restore="${id}"]`)?.remove();if(w._opener?.isConnected)w._opener.focus({preventScroll:true})}
function dragWindow(w){const bar=w.querySelector('.window-title');let drag=null;bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||w.classList.contains('maximized')||innerWidth<650)return;const r=w.getBoundingClientRect();drag={x:e.clientX-r.x,y:e.clientY-r.y};w.style.transform='none';w.style.left=r.x+'px';w.style.top=r.y+'px';bar.setPointerCapture(e.pointerId)});bar.addEventListener('pointermove',e=>{if(!drag)return;w.style.left=Math.max(0,Math.min(innerWidth-w.offsetWidth,e.clientX-drag.x))+'px';w.style.top=Math.max(61,Math.min(innerHeight-135,e.clientY-drag.y))+'px'});bar.addEventListener('pointerup',()=>drag=null);bar.addEventListener('pointercancel',()=>drag=null)}
document.addEventListener('click',e=>{let a=e.target.closest('[data-open]');if(a)openApp(a.dataset.open);let p=e.target.closest('[data-project]');if(p)showProject(p.dataset.project)});document.querySelector('.brand').onclick=e=>{e.preventDefault();[...wins.keys()].forEach(closeApp);window.scrollTo({top:0,behavior:paused?'instant':'smooth'})};document.addEventListener('keydown',e=>{if(e.altKey&&['1','2','3'].includes(e.key)){e.preventDefault();openApp({'1':'projects','2':'lab','3':'terminal'}[e.key])}if(e.key==='Escape'){let visible=[...wins.values()].filter(w=>!w.hidden).sort((a,b)=>+b.style.zIndex-+a.style.zIndex);if(visible[0])closeApp(visible[0].dataset.app)}});
function renderApp(id,el){if(id==='projects')renderProjects(el);if(id==='about')el.innerHTML=`<span class="eyebrow">THE HUMAN BEHIND THE EXPERIMENTS</span><h2>Hi, I’m Sudhanshu.</h2><p class="lede">I’m drawn to the space between understanding something and making it work. My work moves between machine learning, quantitative systems, and software engineering.</p><p class="lede">I like the questions at the edges: where a model meets noisy data, where an observed opportunity meets execution constraints, and where a theory becomes something you can test.</p><div class="achievement"><strong>100 percentile · Physics</strong><p>JEE Main · March 2021 attempt</p><p>A small part of the story. The curiosity stayed.</p></div><h3>On my workbench</h3><div>${['Python','C++','Java','C','MATLAB','R','Time-series analysis','Statistical modeling','Anomaly detection','Predictive analytics'].map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="detail-actions"><button class="primary" data-open="projects">Explore the projects</button><a href="https://www.linkedin.com/in/sudhanshu-bhale" target="_blank" rel="noopener">LinkedIn profile</a></div>`;
if(id==='contact')el.innerHTML=`<span class="eyebrow">LET’S COMPARE NOTES</span><h2>Good ideas start<br>with a conversation.</h2><p class="lede">Have an interesting engineering problem, an experiment in mind, or a question about my work? Find me here.</p><div class="contact-links"><a href="https://www.linkedin.com/in/sudhanshu-bhale" target="_blank" rel="noopener">LinkedIn<span>sudhanshu-bhale</span></a><a href="https://github.com/thorbus" target="_blank" rel="noopener">GitHub<span>@thorbus</span></a></div>`;
if(id==='notes')el.innerHTML=`<span class="eyebrow">FOUR WAYS OF LOOKING AT A PROBLEM</span><h2>Notes from the margins.</h2><p class="lede">Physics-inspired prompts for approaching a piece of software. These are my lab’s interpretations, not quotations.</p><div class="note-grid"><article class="note"><span class="meta">01 / NEWTON</span><h3>Start with the forces.</h3><div class="formula">F = ma</div><p>What actually moves a system? Map the inputs, constraints, and state changes before adding complexity.</p></article><article class="note"><span class="meta">02 / FARADAY</span><h3>Make the experiment.</h3><div class="formula">ε = −dΦB / dt</div><p>An idea gets more useful when you can test it. Build the smallest version that tells you something new.</p></article><article class="note"><span class="meta">03 / MAXWELL</span><h3>Find the connection.</h3><div class="formula">c = 1 / √(μ₀ε₀)</div><p>Separate mechanisms can belong to the same system. Look for the model that makes their relationship clear.</p></article><article class="note"><span class="meta">04 / FEYNMAN</span><h3>Explain it plainly.</h3><div class="formula">understand → build → explain</div><p>If a system needs a wall of jargon, return to the basics. Clear explanations reveal the missing pieces.</p></article></div><div class="detail-actions"><button class="primary" data-open="lab">Try a physics experiment</button></div>`;
if(id==='experience')el.innerHTML=`<span class="eyebrow">EXPERIENCE & FOUNDATIONS</span><h2>Learning by building.</h2><div class="experience-entry"><span class="meta">PROFESSIONAL EXPERIENCE</span><h3>Rtifact</h3><a href="https://www.linkedin.com/in/sudhanshu-bhale" target="_blank" rel="noopener">View professional history on LinkedIn</a></div><div class="experience-entry"><span class="meta">EDUCATION</span><h3>Indian Institute of Information Technology Vadodara</h3></div><h3>Engineering toolkit</h3><div>${['Python','C++','Java','C','MATLAB','R','Pandas','NumPy','Matplotlib'].map(t=>`<span class="tag">${t}</span>`).join('')}</div><p>Clustering · Time-series analysis · Statistical modeling · Anomaly detection · Predictive analytics</p><div class="achievement"><strong>100 percentile in Physics</strong><p>JEE Main · March 2021</p></div><button class="primary" data-open="projects">Explore selected work</button>`;if(id==='terminal')renderTerminal(el);if(id==='lab')renderLab(el)}
function renderProjects(el){el.innerHTML=`<span class="eyebrow">SELECTED WORK / QUANTITATIVE EXPLORATIONS</span><h2>Models meet the real world.</h2><p class="lede">Two investigations into prediction markets: a system for detecting opportunities, and the research to understand them.</p><div class="curated-list">${projects.map((p,i)=>`<button class="curated-project" data-project="${p.id}"><span class="meta">0${i+1} / ${p.category}</span><h3>${p.title}</h3><p>${p.description}</p><div>${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><span class="case-open">Explore case study ＋</span></button>`).join('')}</div>`}
function showProject(id){const p=projects.find(p=>p.id===id);if(!p)return;let w=openApp('projects'),el=w.querySelector('.window-content');el.innerHTML=`<div class="detail-top"><button class="back" id="back-projects">‹ Selected work</button></div><span class="eyebrow">${p.category} / BTC PREDICTION MARKETS</span><h2>${p.title}</h2><p class="lede">${p.description}</p><div>${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="detail-body"><h3>The engineering</h3><ul>${p.features.map(t=>`<li>${t}</li>`).join('')}</ul></div>${id==='arbitrage'?`<div class="market-demo"><div class="card-meta"><span>EXPLORE THE MODEL</span><span>ILLUSTRATIVE INPUTS</span></div><h3>When does the gap survive costs?</h3><div class="price-inputs"><label>YES price <span><input id="yes-price" type="range" min="0.1" max="0.85" step="0.01" value="0.46"><output id="yes-out">$0.46</output></span></label><label>NO price <span><input id="no-price" type="range" min="0.1" max="0.85" step="0.01" value="0.49"><output id="no-out">$0.49</output></span></label><label>Costs per pair <span><input id="cost-price" type="range" min="0" max="0.15" step="0.005" value="0.02"><output id="cost-out">$0.020</output></span></label></div><div class="model-result" aria-live="polite"><div><span>COMBINED COST</span><strong id="combined-price"></strong></div><div><span>THEORETICAL NET EDGE</span><strong id="net-edge"></strong></div></div><p class="demo-note">Simplified arithmetic for a complementary outcome pair settling to $1. Sample inputs, not live quotes or measured performance. Actual execution also depends on fills, liquidity, and settlement rules.</p></div>`:`<div class="research-flow"><span>01 / OBSERVE</span><h3>High-frequency pricing</h3><p>Capture opposing outcome prices and follow their combined spread over time.</p><span>02 / MEASURE</span><h3>Frequency & persistence</h3><p>Ask how often an opportunity appears, how long it lasts, and what survives transaction costs.</p><span>03 / CHALLENGE</span><h3>Execution friction</h3><p>Backtest thresholds with delays and costs, rather than assuming every observed quote is executable.</p></div>`}<div class="detail-actions"><button class="primary" data-open="contact">Let’s talk about the work</button><button class="text-button" data-open="lab">Visit the physics lab</button></div>`;el.querySelector('#back-projects').onclick=()=>renderProjects(el);el.scrollTop=0;if(id==='arbitrage'){const update=()=>{const y=+el.querySelector('#yes-price').value,n=+el.querySelector('#no-price').value,c=+el.querySelector('#cost-price').value;el.querySelector('#yes-out').value='$'+y.toFixed(2);el.querySelector('#no-out').value='$'+n.toFixed(2);el.querySelector('#cost-out').value='$'+c.toFixed(3);el.querySelector('#combined-price').textContent='$'+(y+n+c).toFixed(3);const edge=1-y-n-c;el.querySelector('#net-edge').textContent=(edge>=0?'+':'−')+'$'+Math.abs(edge).toFixed(3);el.querySelector('#net-edge').style.color=edge>0?'var(--green)':'var(--orange)'};el.querySelectorAll('input').forEach(i=>i.oninput=update);update()}}
function renderTerminal(el){el.style.padding='0';el.innerHTML=`<div class="terminal-content"><p>CURIOSITY ENGINE / interactive shell v0.2<br><span class="terminal-muted">A small directory of a curious mind.</span></p><p class="terminal-muted">Try help, whoami, ls, open projects, open lab, or clear.</p><div id="terminal-output" role="log" aria-live="polite"></div><form class="terminal-form"><label for="command">explorer@universe:~ $</label><input id="command" aria-label="Terminal command" autocomplete="off" spellcheck="false"></form></div>`;let hist=[],cursor=0;const input=el.querySelector('input'),output=el.querySelector('#terminal-output');el.querySelector('form').onsubmit=e=>{e.preventDefault();const cmd=input.value.trim();if(!cmd)return;hist.push(cmd);cursor=hist.length;input.value='';if(cmd.toLowerCase()==='clear'){output.replaceChildren();return}const line=document.createElement('p');line.textContent='explorer@universe:~ $ '+cmd;output.append(line);let response='',lower=cmd.toLowerCase();if(lower==='help')response='whoami          About Sudhanshu\nls              List selected case studies\nopen <app>      games, atlas, projects, experience, lab, notes, about, contact\nphysics         Open the physics playground\ngithub          Show GitHub profile\nclear           Clear this terminal';else if(lower==='whoami')response='Sudhanshu Bhale\nMachine learning, quantitative systems, and first-principles thinking.\nGitHub: https://github.com/thorbus';else if(lower==='ls')response=projects.map(p=>p.id).join('\n');else if(lower==='github')response='https://github.com/thorbus';else if(lower==='physics'){openApp('lab');response='Opened: Physics playground'}else if(lower.startsWith('open ')){let id=lower.slice(5).trim();if(titles[id]){openApp(id);response='Opened: '+titles[id]}else response='Unknown app. Try: games, atlas, projects, experience, lab, notes, about, contact.'}else response='Command not found: '+cmd+'\nType help to see the available commands.';const result=document.createElement('p');result.textContent=response;output.append(result);el.scrollTop=el.scrollHeight};input.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();cursor=Math.max(0,cursor-1);input.value=hist[cursor]||''}if(e.key==='ArrowDown'){e.preventDefault();cursor=Math.min(hist.length,cursor+1);input.value=hist[cursor]||''}}}
let labMode='newton',labTime=0,labPaused=false,labValue=.42;const labInfo={newton:{name:'Newton · Orbital mechanics',desc:'An idealized two-body orbit. Increase eccentricity to stretch the ellipse. The planet moves faster near the central mass, following Kepler’s equation. Distances and time are normalized.',formula:'F = Gm₁m₂ / r²',label:'Eccentricity',min:0,max:.8,step:.01,value:.42},faraday:{name:'Faraday · Electromagnetic induction',desc:'A changing magnetic flux induces an electromotive force. Increase the frequency to see the induced voltage grow. The voltage is the negative time derivative of the flux; the traces use normalized units.',formula:'ε = −dΦB / dt',label:'Frequency',min:.3,max:2,step:.1,value:1},maxwell:{name:'Maxwell · An electromagnetic wave',desc:'Electric and magnetic fields oscillate together, perpendicular to each other and to the direction of travel. This projected diagram scales both fields for visibility; amplitude and time are normalized.',formula:'c = 1 / √(μ₀ε₀)',label:'Amplitude',min:.2,max:1,step:.05,value:.65},feynman:{name:'Feynman · Two paths, one pattern',desc:'An idealized, monochromatic double-slit pattern in the far field. Increasing slit separation brings the bright fringes closer together. The envelope includes a fixed finite slit width.',formula:'I(θ) ∝ sinc²(πα sinθ / λ) · cos²(πd sinθ / λ)',label:'Slit separation',min:2,max:8,step:.1,value:4}};
function renderLab(el){const info=labInfo[labMode];labValue=info.value;el.innerHTML=`<span class="eyebrow">CHANGE A PARAMETER. FOLLOW THE CONSEQUENCE.</span><h2>A small physics playground.</h2><div class="filters" role="group" aria-label="Physics experiment">${Object.keys(labInfo).map(k=>`<button class="filter ${labMode===k?'active':''}" aria-pressed="${labMode===k}" data-experiment="${k}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><canvas id="lab-canvas" class="lab-view" aria-label="${info.name} interactive diagram"></canvas><div class="lab-controls"><label>${info.label}<input id="lab-range" type="range" min="${info.min}" max="${info.max}" step="${info.step}" value="${info.value}"><output id="lab-output">${info.value}</output></label><button class="filter" id="lab-pause">${labPaused?'Resume':'Pause'}</button><button class="filter" id="lab-reset">Reset</button></div><div class="lab-description"><h3>${info.name}</h3><div class="lab-equation">${info.formula}</div><p>${info.desc}</p></div>`;el.querySelectorAll('[data-experiment]').forEach(b=>b.onclick=()=>{labMode=b.dataset.experiment;labTime=0;renderLab(el)});const input=el.querySelector('#lab-range');input.oninput=()=>{labValue=+input.value;el.querySelector('#lab-output').value=input.value};el.querySelector('#lab-pause').onclick=e=>{labPaused=!labPaused;e.target.textContent=labPaused?'Resume':'Pause'};el.querySelector('#lab-reset').onclick=()=>{labTime=0;labPaused=false;renderLab(el)}}
function drawLab(dt){const c=document.querySelector('#lab-canvas');if(!c||wins.get('lab')?.hidden)return;if(!labPaused&&!paused)labTime+=dt;let[w,h,x]=fit(c);if(labMode==='newton'){drawOrbit(c,labTime*.7,labValue);return}x.clearRect(0,0,w,h);const left=35,right=w-25,mid=h/2;function grid(){x.strokeStyle='#77946b20';x.lineWidth=1;for(let a=left;a<right;a+=35){x.beginPath();x.moveTo(a,25);x.lineTo(a,h-25);x.stroke()}for(let y=25;y<h-20;y+=35){x.beginPath();x.moveTo(left,y);x.lineTo(right,y);x.stroke()}x.strokeStyle='#7c976155';x.beginPath();x.moveTo(left,mid);x.lineTo(right,mid);x.stroke()}grid();x.font='12px monospace';if(labMode==='faraday'){let amp=h*.21;x.fillStyle='#d3ef97';x.fillText('ΦB magnetic flux',left,22);x.fillStyle='#eda76c';x.fillText('ε induced voltage',left,40);for(let n=0;n<2;n++){x.strokeStyle=n?'#eda76c':'#d3ef97';x.lineWidth=2;x.beginPath();for(let p=0;p<=right-left;p++){let t=p/(right-left)*Math.PI*4+labTime*labValue;let v=n?-labValue*Math.cos(t):Math.sin(t);let y=mid-v*amp;p?x.lineTo(left+p,y):x.moveTo(left+p,y)}x.stroke()}}else if(labMode==='maxwell'){x.fillStyle='#d3ef97';x.fillText('E · electric field',left,22);x.fillStyle='#eda76c';x.fillText('B · magnetic field (scaled)',left,40);for(let n=0;n<2;n++){x.strokeStyle=n?'#eda76c':'#d3ef97';x.lineWidth=2;x.beginPath();for(let p=0;p<=right-left;p++){let v=Math.sin(p/(right-left)*Math.PI*4-labTime*1.8)*labValue*h*.3;let xx=left+p+(n?v*.3:0),yy=mid-v*(n?-.45:1);p?x.lineTo(xx,yy):x.moveTo(xx,yy)}x.stroke();x.lineWidth=1;x.globalAlpha=.35;for(let p=0;p<right-left;p+=14){let v=Math.sin(p/(right-left)*Math.PI*4-labTime*1.8)*labValue*h*.3;x.beginPath();x.moveTo(left+p,mid);x.lineTo(left+p+(n?v*.3:0),mid-v*(n?-.45:1));x.stroke()}x.globalAlpha=1}x.fillStyle='#9eaf91';x.fillText('propagation: +x',right-120,h-18)}else{const base=h-45;for(let p=0;p<right-left;p++){let u=(p/(right-left)-.5)*3,alpha=Math.PI*.7*u,env=Math.abs(alpha)<.001?1:(Math.sin(alpha)/alpha)**2,I=env*Math.cos(Math.PI*labValue*u)**2;x.fillStyle=`rgba(211,239,151,${.06+I*.94})`;x.fillRect(left+p,65,1,45)}x.strokeStyle='#d3ef97';x.lineWidth=2;x.beginPath();for(let p=0;p<=right-left;p++){let u=(p/(right-left)-.5)*3,alpha=Math.PI*.7*u,env=Math.abs(alpha)<.001?1:(Math.sin(alpha)/alpha)**2,I=env*Math.cos(Math.PI*labValue*u)**2,y=base-I*(h-165);p?x.lineTo(left+p,y):x.moveTo(left+p,y)}x.stroke();x.fillStyle='#a7b696';x.fillText('SCREEN · bright fringes',left,30);x.fillText('Relative intensity',left,h-17)}}
window.addEventListener('resize',()=>{for(const w of wins.values()){w.style.left='';w.style.top='';w.style.transform=''}});
